<?php
require_once __DIR__.'/includes/functions.php'; $pageTitle='Book Catalog';
$q=trim($_GET['q']??'');$category=(int)($_GET['category']??0);$availability=$_GET['availability']??'';$sort=$_GET['sort']??'newest';
$where=['b.is_active=1'];$params=[];
if($q!==''){$where[]='(b.title LIKE ? OR b.author LIKE ? OR b.isbn LIKE ? OR c.name LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}
if($category>0){$where[]='b.category_id=?';$params[]=$category;}
if($availability==='available')$where[]='b.available_quantity>0';elseif($availability==='unavailable')$where[]='b.available_quantity=0';
$order=['newest'=>'b.created_at DESC','title'=>'b.title ASC','author'=>'b.author ASC','popular'=>'b.times_issued DESC'][$sort]??'b.created_at DESC';
$sql='SELECT b.*,c.name AS category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE '.implode(' AND ',$where).' ORDER BY '.$order;
$stmt=db()->prepare($sql);$stmt->execute($params);$books=$stmt->fetchAll();$categories=db()->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
require __DIR__.'/includes/header.php';
?>
<div class="d-flex justify-content-between align-items-end flex-wrap gap-3 mb-4"><div><p class="text-primary text-uppercase small fw-bold mb-1">Discover something new</p><h1 class="page-title mb-1">Book catalog</h1><p class="muted mb-0"><?=count($books)?> result<?=count($books)===1?'':'s'?> in the library</p></div></div>
<form class="filter-bar mb-4" method="get"><div class="row g-2 align-items-end"><div class="col-lg-5"><label class="form-label">Search books</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Title, author, ISBN, category..."></div><div class="col-sm-6 col-lg-3"><label class="form-label">Category</label><select class="form-select" name="category"><option value="0">All categories</option><?php foreach($categories as $c): ?><option value="<?=(int)$c['id']?>" <?=$category===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></div><div class="col-sm-6 col-lg-2"><label class="form-label">Availability</label><select class="form-select" name="availability"><option value="">Any status</option><option value="available" <?=$availability==='available'?'selected':''?>>Available</option><option value="unavailable" <?=$availability==='unavailable'?'selected':''?>>Checked out</option></select></div><div class="col-sm-6 col-lg-2"><label class="form-label">Sort by</label><select class="form-select" name="sort"><option value="newest" <?=$sort==='newest'?'selected':''?>>Recently added</option><option value="title" <?=$sort==='title'?'selected':''?>>Title A–Z</option><option value="author" <?=$sort==='author'?'selected':''?>>Author A–Z</option><option value="popular" <?=$sort==='popular'?'selected':''?>>Most borrowed</option></select></div><div class="col-12 d-flex gap-2 mt-2"><button class="btn btn-primary" type="submit"><i class="bi bi-search me-1"></i> Apply filters</button><a class="btn btn-light" href="catalog.php">Reset</a></div></div></form>
<div class="row g-3"><?php if(!$books): ?><div class="col-12"><div class="surface empty-state"><i class="bi bi-search d-block mb-2"></i><h5>No books found</h5><p>Try a different title, author, or filter.</p><a class="btn btn-outline-primary" href="catalog.php">Clear filters</a></div></div><?php endif; ?>
<?php foreach($books as $b): ?><div class="col-6 col-md-4 col-xl-3"><article class="book-card"><a href="book.php?id=<?=(int)$b['id']?>" class="text-decoration-none text-reset"><div class="book-cover"><img src="<?=e(cover_url($b['cover_image']))?>" alt="<?=e($b['title'])?> cover" loading="lazy"></div><div class="card-body"><span class="badge-soft"><?=e($b['category_name']??'General')?></span><h2 class="book-title mt-2 mb-1"><?=e($b['title'])?></h2><p class="muted small mb-3"><?=e($b['author'])?></p><div class="d-flex justify-content-between align-items-center gap-1"><span class="small muted"><?= (int)$b['available_quantity'] ?> available</span><span class="<?= $b['available_quantity']>0?'badge-available':'badge-unavailable' ?> badge-soft"><?= $b['available_quantity']>0?'In stock':'Checked out' ?></span></div></div></a></article></div><?php endforeach; ?></div>
<?php require __DIR__.'/includes/footer.php'; ?>
